import pandas as pd,numpy as np,re
from sklearn.feature_extraction.text import CountVectorizer
from sklearn.linear_model import RidgeCV
from sklearn.ensemble import GradientBoostingRegressor,RandomForestRegressor
tr=pd.read_csv('b3_pvk_open_train.csv');po=pd.read_csv('b3_pvk_open_pool.csv')
cols=['composition','architecture','substrate','etl','htl','backcontact','deposition']
KNOWN=set()
def feats(df):
    rows=[]
    for _,r in df.iterrows():
        t=[]
        for c in cols:
            for part in re.split(r'\||>>|;|@',str(r[c])):
                part=part.strip()
                if part: t.append(c+'='+part.replace(' ','_'))
        comp=str(r['composition'])
        # engineered
        if '|' in comp: t.append('ENG=2Dcap')
        if comp.startswith('('): t.append('ENG=quasi2D_bulk')
        for ion,tag in [('Cs','Cs'),('FA','FA'),('MA','MA'),('Sn','Sn'),('Bi','Bi'),('Sb','Sb'),('Ag','AgB')]:
            if ion in comp: t.append('ION='+tag)
        if 'Br' in comp and 'I' in comp: t.append('ION=mixhal')
        ncat=sum(x in comp for x in ['Cs','FA','MA'])
        t.append('NCAT=%d'%ncat)
        nhtl=len(str(r['htl']).split('|'))
        if nhtl>1: t.append('ENG=htl_interlayer')
        if len(str(r['etl']).split('|'))>1: t.append('ENG=etl_multi')
        rows.append(' '.join(t))
    return rows
X=feats(tr);Xp=feats(po)
cv=CountVectorizer(token_pattern=r'\S+',binary=True);A=cv.fit_transform(X).toarray();B=cv.transform(Xp).toarray()
y=tr.target.values
from sklearn.model_selection import cross_val_score,KFold
ms=[('ridge',RidgeCV(alphas=np.logspace(-2,3,40))),('gbr',GradientBoostingRegressor(random_state=0,n_estimators=300,max_depth=2,learning_rate=0.05)),('rf',RandomForestRegressor(n_estimators=800,random_state=0,min_samples_leaf=2))]
P={}
for n,m in ms:
    print(n,cross_val_score(m,A,y,cv=KFold(5,shuffle=True,random_state=1),scoring='r2').mean().round(3))
    m.fit(A,y);P[n]=m.predict(B)
D=pd.DataFrame(P,index=po.candidate_id);D['avg']=D.mean(1)
D=D.join(po.set_index('candidate_id')[['composition','architecture','etl','htl','backcontact']])
print(D.sort_values('avg',ascending=False).head(25).round(2).to_string())
"

